import org.cef.*;
import org.cef.browser.*;
import org.cef.handler.*;
import org.cef.network.*;
import org.cef.misc.*;
import org.cef.callback.*;
import dev.netlab.media.client.*;
import java.awt.Rectangle;
import java.nio.*;
import java.nio.file.*;
import java.util.concurrent.atomic.*;
/** Actual bundled Chromium: local IPTV player HTML, decoded video/audio, shared-clock seek. No Minecraft. */
public final class MediaChromiumRuntimeCheck {
    static CefResourceHandler resource(byte[] body,String type){return new CefResourceHandlerAdapter(){int offset;public boolean processRequest(CefRequest request,CefCallback callback){callback.Continue();return true;}public void getResponseHeaders(CefResponse response,IntRef length,StringRef redirect){response.setStatus(200);response.setMimeType(type);length.set(body.length);}public boolean readResponse(byte[] data,int max,IntRef read,CefCallback callback){int n=Math.min(max,body.length-offset);if(n<=0){read.set(0);return false;}System.arraycopy(body,offset,data,0,n);offset+=n;read.set(n);return true;}};}
    public static void main(String[] args)throws Exception{
        System.setProperty("jcef.path",args[0]);System.setProperty("jcef.external_message_pump","true");dev.netlab.sputnik.client.NativeBrowserLibraries.prepare();String[] switches={"--disable-gpu","--disable-background-networking","--autoplay-policy=no-user-gesture-required"};if(!CefApp.startup(switches))throw new AssertionError("CEF startup failed");var settings=new CefSettings();settings.windowless_rendering_enabled=true;settings.log_severity=CefSettings.LogSeverity.LOGSEVERITY_ERROR;settings.log_file="/tmp/netlab-media-cef.log";var app=CefApp.getInstance(switches,settings);var client=app.createClient();long deadline=System.nanoTime()+30_000_000_000L;while(CefApp.getState()!=CefApp.CefAppState.INITIALIZED&&System.nanoTime()<deadline){app.N_DoMessageLoopWork();Thread.sleep(10);}if(CefApp.getState()!=CefApp.CefAppState.INITIALIZED)throw new AssertionError("CEF init");var context=CefRequestContext.createContext(new CefRequestContextSettings(),new CefRequestContextHandlerAdapter(){});byte[] video=Files.readAllBytes(Path.of(args[1]));var audio=new AtomicBoolean();var paint=new AtomicBoolean();var seek=new AtomicBoolean();var failure=new AtomicReference<String>();
        client.addRequestHandler(new CefRequestHandlerAdapter(){public CefResourceRequestHandler getResourceRequestHandler(CefBrowser b,CefFrame f,CefRequest q,boolean navigation,boolean download,String initiator,BoolRef disable){return new CefResourceRequestHandlerAdapter(){public CefResourceHandler getResourceHandler(CefBrowser b,CefFrame f,CefRequest q){if(q.getURL().equals("https://netlab.media/player"))return new HtmlResource(PlayerPage.html("https://netlab.media/check.webm",2));if(q.getURL().equals("https://netlab.media/check.webm"))return resource(video,"video/webm");return resource(new byte[0],"text/plain");}};}});
        client.addLifeSpanHandler(new CefLifeSpanHandlerAdapter(){public void onAfterCreated(CefBrowser b){b.setWindowVisibility(true);b.setWindowlessFrameRate(20);b.loadURL("https://netlab.media/player");}});
        client.addAudioHandler(new CefAudioHandlerAdapter(){public boolean getAudioParameters(CefBrowser b,CefAudioParameters p){p.sampleRate=24000;p.framesPerBuffer=2400;p.channelLayout=CefChannelLayout.CEF_CHANNEL_LAYOUT_MONO;return true;}public void onAudioStreamPacket(CefBrowser b,DataPointer p,int frames,long pts){if(frames>0)audio.set(true);}});
        client.addDisplayHandler(new CefDisplayHandlerAdapter(){public boolean onConsoleMessage(CefBrowser b,CefSettings.LogSeverity severity,String message,String source,int line){if(message.equals("MEDIA_SEEK_OK"))seek.set(true);if(message.startsWith("MEDIA_ERROR"))failure.set(message);return true;}});
        var browser=new CefBrowserOsr(client,"about:blank",false,context){public Rectangle getViewRect(CefBrowser b){return new Rectangle(0,0,640,360);}public void onPaint(CefBrowser b,boolean popup,Rectangle[] dirty,ByteBuffer bytes,int w,int h){if(w>0&&h>0)paint.set(true);}};browser.createImmediately();long last=0;
        while(System.nanoTime()<deadline&&!(audio.get()&&paint.get()&&seek.get())){app.N_DoMessageLoopWork();long now=System.nanoTime();if(now-last>400_000_000L){browser.executeJavaScript("(()=>{let v=document.querySelector('video');if(v&&Number.isFinite(v.duration)&&v.readyState>=2){if(!window.__asked){window.netlabSeek(6);window.__asked=true;}else if(v.currentTime>=5)console.log('MEDIA_SEEK_OK');if(v.error)console.log('MEDIA_ERROR:'+v.error.code)}})()","https://netlab.media/player",0);last=now;}Thread.sleep(10);}
        boolean ok=audio.get()&&paint.get()&&seek.get()&&failure.get()==null;browser.close(true);long until=System.nanoTime()+800_000_000L;while(System.nanoTime()<until){app.N_DoMessageLoopWork();Thread.sleep(10);}client.dispose();context.dispose();app.dispose();String result="Standalone Media Chromium: paint="+paint+", decoded PCM="+audio+", schedule seek="+seek+", error="+failure.get();System.out.println(result+". No Minecraft, server, microphone or world launched.");if(!ok)throw new AssertionError(result);
    }
}
